grids.grid:










































      &DefaultButton;




declare @strKey nvarchar(3000)
set @strKey = 'ky = ' + rtrim(@ky) + ' and nam = ' + rtrim(@nam)
if @@admin = 0 and exists(select 1 from dmnvbh where user_id = @@userId)
  set @strKey = @strKey + ' and a.ma_kh in (select ma_kh from dmkh where ma_nvbh in (select ma_nvbh from dbo.sf_GetEmployeeList(@@userId)))'

exec ISWIFTStoreTableLoading '@@table', '@@fieldKey', '@@fields', @@fieldOrder, '', '', 'left join dmnvbh b on a.ma_nvbh = b.ma_nvbh left join dmvt c on a.ma_vt = c.ma_vt left join dmkh d on a.ma_kh = d.ma_kh', 'b.ten_nvbh, c.ten_vt, d.ten_kh', '@@key', @strKey, @@filterKey, '', @pageIndex, 50, @@admin, @@userId

js.text:

function grid$cnkhbh(f){
  this.constructor(f);
}
grid$cnkhbh.prototype = new DirEvent();
grid$cnkhbh.prototype.afterInit = function(){
  var p = this._dir;
}

css.text:

.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
